WITH c AS (SELECT q.* FROM dictation_question q WHERE q.subject_id = CAST(:subject_id AS INTEGER) AND q.enabled = 1 AND q.kind = :direction AND (:level = '' OR q.level = :level) AND (:source = '' OR q.point_code = :source) AND instr(',' || :asked_ids || ',', ',' || q.id || ',') = 0 AND q.id NOT IN (SELECT question_id FROM dictation_question_attempt WHERE learner = :learner AND subject_id = CAST(:subject_id AS INTEGER) AND direction = :direction)) SELECT id, code, point_code, kind, level, prompt_zh, COALESCE(prompt_ja, '') AS prompt_ja, answer, accepted_json, COALESCE(explain_zh, '') AS explain_zh, COALESCE(explain_ja, '') AS explain_ja, enabled FROM c ORDER BY id LIMIT 1 OFFSET (CAST(:seed AS INTEGER) % MAX((SELECT COUNT(*) FROM c), 1))
